python3 -c "
import json
with open('/app/resources/treasury_bulletin_1972_04.json') as f:
    data = json.load(f)
# Search for any 'exchange' or 'rate' related sections
def search(obj, path=''):
    if isinstance(obj, dict):
        for k, v in obj.items():
            if 'exchange' in k.lower() or 'rate' in k.lower() or 'foreign' in k.lower():
                print(f'{path}.{k}: {str(v)[:200]}')
            search(v, path + '.' + k)
    elif isinstance(obj, list):
        for i, item in enumerate(obj[:5]):
            search(item, path + f'[{i}]')
search(data)
